package phpupdate

import (
	"strconv"
	"strings"
)

// Accept only the invocation generated by Fluxo's Nightwatch feature. This is
// an ordinary telemetry-agent stop, not a promise of graceful buffer flushing.
func managedNightwatchPort(branch, command string) (int, bool) {
	prefix := "php" + branch + " artisan nightwatch:agent --listen-on=127.0.0.1:"
	if !strings.HasPrefix(command, prefix) {
		return 0, false
	}
	text := strings.TrimPrefix(command, prefix)
	port, err := strconv.Atoi(text)
	return port, err == nil && port >= 1024 && port <= 65535 && strconv.Itoa(port) == text
}
